let cart = JSON.parse(localStorage.getItem('obs_cart') || '[]');
let owned = JSON.parse(localStorage.getItem('obs_owned') || '[]');
let wishlist = JSON.parse(localStorage.getItem('obs_wishlist') || '[]');
let favorites = JSON.parse(localStorage.getItem('obs_favorites') || '[]');
let loggedIn = localStorage.getItem('obs_logged_in') === '1';

function save(key, val){ localStorage.setItem(key, JSON.stringify(val)); }

function starBtn(id){
  const on = favorites.includes(id);
  return `<button onclick="toggleFav(event, ${id})" class="absolute top-2 right-2 w-7 h-7 flex items-center justify-center bg-cream/90 text-lg ${on?'text-gold':'text-inksoft'}">&#9733;</button>`;
}

function bookCard(b){
  const priceHtml = b.oldPrice
    ? `<span class="line-through text-inksoft text-xs mr-1">$${b.oldPrice}</span><span class="text-rust font-semibold font-mono">$${b.price}</span>`
    : (b.price === 0 ? `<span class="text-good font-semibold font-mono">Free</span>` : `<span class="font-semibold font-mono">$${b.price}</span>`);
  const badge = b.oldPrice ? `<span class="absolute top-2 left-2 chip-cart text-[10px] font-bold px-2 py-1">SALE</span>` : (b.price===0 ? `<span class="absolute top-2 left-2 bg-good text-cream text-[10px] font-bold px-2 py-1">FREE</span>` : '');
  return `<div class="bg-white border border-sand relative">
    ${badge}${starBtn(b.id)}
    <a href="book.html?id=${b.id}"><img src="${b.cover}" class="w-full h-40 object-cover"></a>
    <div class="p-4">
      <a href="category.html?cat=${encodeURIComponent(b.category)}" class="text-[10px] uppercase tracking-wide text-rust mb-1 font-mono block">${b.category}</a>
      <a href="book.html?id=${b.id}"><h3 class="font-serif font-semibold text-sm leading-snug hover:text-rust">${b.title}</h3></a>
      <p class="text-xs text-inksoft mb-3">${b.author}</p>
      <div class="flex justify-between items-center gap-2">
        <span class="text-sm">${priceHtml}</span>
        <div class="flex gap-1">
          <button onclick="toggleWish(event, ${b.id})" class="text-[11px] border border-ink px-2 py-1.5 hover:bg-ink hover:text-cream">+ Wish</button>
          <button onclick="handleAdd(event, ${b.id})" class="text-[11px] chip-cart px-2 py-1.5">Add</button>
        </div>
      </div>
    </div>
  </div>`;
}
function handleAdd(e, id){
  e.preventDefault();
  const b = books.find(x=>x.id===id);
  if(b.price > 0 && !loggedIn){ showLoginGate(); return; }
  addToCart(id);
}
function addToCart(id){ cart.push(id); save('obs_cart', cart); updateCartUI(); openCart(); }
function removeFromCart(i){ cart.splice(i,1); save('obs_cart', cart); updateCartUI(); }
function toggleFav(e, id){ e.preventDefault();
  favorites = favorites.includes(id) ? favorites.filter(x=>x!==id) : [...favorites, id];
  save('obs_favorites', favorites);
  document.querySelectorAll('[data-refresh]').forEach(fn=>{}); location.reload();
}
function toggleWish(e, id){ e.preventDefault();
  wishlist = wishlist.includes(id) ? wishlist.filter(x=>x!==id) : [...wishlist, id];
  save('obs_wishlist', wishlist);
  alert(wishlist.includes(id) ? 'Added to wishlist.' : 'Removed from wishlist.');
}

function openCart(){ const p = document.getElementById('cartPanel'); if(p) p.classList.remove('translate-x-full'); }
function toggleCart(){ document.getElementById('cartPanel').classList.toggle('translate-x-full'); }
function updateCartUI(){
  const countEl = document.getElementById('cartCount');
  if(!countEl) return;
  countEl.textContent = cart.length;
  const items = cart.map(id => books.find(b=>b.id===id));
  const total = items.reduce((s,b)=>s+b.price,0);
  document.getElementById('cartItems').innerHTML = items.map((b,i)=>`
    <div class="flex justify-between items-center text-sm border-b border-sand pb-2">
      <span>${b.title}</span>
      <div class="flex items-center gap-2"><span class="font-mono">${b.price===0?'Free':'$'+b.price}</span>
      <button onclick="removeFromCart(${i})" class="text-inksoft text-xs">&#10005;</button></div>
    </div>`).join('') || '<p class="text-inksoft text-sm">Cart is empty.</p>';
  const totalEl = document.getElementById('cartTotal');
  if(totalEl) totalEl.textContent = '$' + total.toFixed(2);
}

function showLoginGate(){ document.getElementById('loginGate').classList.remove('hidden'); document.getElementById('loginGate').classList.add('flex'); }
function hideLoginGate(){ document.getElementById('loginGate').classList.add('hidden'); document.getElementById('loginGate').classList.remove('flex'); }
function fakeLogin(method){ loggedIn = true; localStorage.setItem('obs_logged_in','1'); hideLoginGate(); alert('Signed in (' + method + ' demo). This is a UI simulation — real OAuth needs backend setup.'); }

