function initSplash(){
  window.addEventListener('load', function(){
    setTimeout(function(){ const s = document.getElementById('splash'); if(s) s.classList.add('hide'); }, 550);
  });
}

document.addEventListener('DOMContentLoaded', function(){
  updateCartUI(); initSplash();
  document.addEventListener('click', function(e){
    const panel = document.getElementById('cartPanel');
    const btn = e.target.closest('[onclick="toggleCart()"]');
    if(panel && !panel.classList.contains('translate-x-full') && !panel.contains(e.target) && !btn){
      panel.classList.add('translate-x-full');
    }
  });
});
